      description:
        '男，20岁。延宋四皇子，明教光明特使，人称「无」。容貌极为俊朗，眉目间透着一股温润清正之气。常年穿着粗布麻衣或寻常江湖客的劲装，不着绫罗绸缎。肤色因常年在外云游而晒成健康的小麦色。行事：隐瞒皇子身份，以寻常江湖游侠的面貌行走四方。',
      personality: '磨砺自身心性，寻访明教旧部后代，化解江湖与朝堂的恩怨。 隐瞒皇子身份，以寻常江湖游侠的面貌行走四方。',
