      description:
        '男，22岁。天龙寺首席弟子，大理段氏嫡系后裔。不穿僧衣，常穿一身素白色的锦缎长衫，袖口绣着暗金色的茶花纹路。面容清俊，五官带着皇室后裔特有的贵气，皮肤白皙。头上不戴冠，只用一根木簪将长发绾起。',
      personality: '扬名天下，重振大理段氏的武道尊严，让朝廷不敢轻易拿捏作为国寺的天龙寺。 待人接物极有教养，无论面对贩夫走卒还是高官显贵，都保持温和有礼的姿态。',
      relationship: '本清方丈 (天龙寺方丈/师尊): 敬重但理念不合。理解师尊向朝廷妥协、让天龙寺成为“大延国寺”的苦衷，但不愿段氏永远做一条摇尾乞怜的狗。；赵德昭 (大延皇帝): 敌视与戒备。深知朝廷将天龙寺立为国寺，只是为了制衡西南武林。；江湖群雄: 结交对象。在江湖上广结善缘，试图建立属于自己的情报与人脉网络，为天龙寺积攒声望。',
