      description:
        '男，68岁。天龙寺方丈，镇南禅师。身披大红金丝袈裟，内衬素白僧衣。面容清癯，长须及胸，皆已花白。身形高大，站立时如苍松挺拔，无老态。行事：面对朝廷钦差或高官时，不卑不亢，仅以佛门礼节相待，绝不谄媚。',
      personality: '维护禅宗正统，保全天龙寺的传承与大理段氏的血脉。 面对朝廷钦差或高官时，不卑不亢，仅以佛门礼节相待，绝不谄媚。',
      relationship: '赵德昭 (大延皇帝): 互相尊重的盟友。接受朝廷“大延国寺”的册封，替朝廷镇守西南武林；同时借助朝廷的势力，保全大理段氏的血脉与天龙寺的超然地位。面对皇帝的密旨，有权根据天龙寺的利益选择性执行。；段无妄 (首席弟子): 寄予厚望。知道段无妄对妥协心存不满，但不加干涉，反而倾注心血培养，将其视为大理段氏在江湖上重新立足的利刃。；智光法王 (大轮寺主持): 宿敌。极度敌视密宗的教义与行事作风。多次下令天龙寺武僧拦截潜入西南的大轮寺番僧，绝不',
