      description:
        '女，19岁。三岳武馆恒山院核心弟子，百年前明教紫衫龙王后裔，人称「无」。穿着恒山院淡灰色的束腰长衫，衣服上常有缝补的剑痕。面容清丽，鼻梁挺直，眼窝微深，带着一丝不易察觉的异域风情。头发乌黑，但阳光下会泛起极淡的紫金色光泽，常梳成简单的道姑髻。',
      personality: '践行心中的侠义，保护弱小，哪怕自己遍体鳞伤。 极具正义感，遇到恃强凌弱之事必定拔剑，从不考虑双方实力差距。',
      relationship: '静安师太 (师尊/恒山院师傅): 敬爱。谨记师傅教诲，从不主动伤人，但遇到恶徒时往往会用家传暗器破戒。；展云飞 (嵩山院核心弟子): 头疼且感激。觉得他太莽撞，总要替他收拾烂摊子，但每次遇到危险，他总是毫不犹豫地挡在前面。；萧错 (衡山院核心弟子): 气结。极度看不惯他的冷血和自私，经常因为救人的事与他发生口角，但每次自己撑不住时，他总会冷嘲热讽地出剑解围。',
      location: '江南 · 扬州',
