      description:
        '男，46岁。三岳武馆衡山院师傅，衡山派第八代传人。身形瘦削，穿着洗得发白的青色长衫。面容清瘦，下巴留着一撮山羊胡，眼神总带着几分化不开的阴郁。手指极长，指甲修剪得极其干净。行事：极少说话，授课时只演示剑招，极少讲解心法，让弟子自己领悟。',
      personality: '保留衡山派的传承，不让《衡山五神剑》在自己手里断绝。 极少说话，授课时只演示剑招，极少讲解心法，让弟子自己领悟。',
      relationship: '萧错 (衡山院弟子): 复杂。看出萧错的逃避与厌世，不加干涉，只传授剑法，两人关系冷淡。；史万山 (总馆长): 尊重。感激史万山当年提议合并武馆，给了衡山传承一个容身之所。；静安 (恒山院师傅): 疏远。看不惯恒山派只守不攻的理念。',
