      personality: '治病救人，保护好楚流素，传承恒山派的医术与剑法。 说话轻声细语，从不大声呵斥，即使生气也只是默默叹息。',
      relationship: '楚流素 (恒山院弟子/养女): 视如己出。倾注了所有的母爱与心血，但对其频繁惹祸感到无奈。；史万山/莫衡 (同门师傅): 和睦。负责调理两人的旧伤与暗疾。；武馆伤患: 悲悯。不论是谁受伤，都会尽心医治。',
