      name: '杨倩希',
      description:
        '女，18岁。古墓派现任掌门，杨氏嫡系传人，人称「无」。容貌极美，继承了杨氏先祖的好相貌，明眸皓齿，顾盼生辉。虽然穿着古墓派规矩的素白长裙，但她偷偷将腰身改窄了几分，显得身形窈窕。头发没有像奶奶那样绾成刻板的发髻，而是用一根白丝带松松垮垮地系着。',
      personality: '找一个长得极度好看、武功高强、对自己一心一意且愿意入赘古墓的如意郎君，完成双修。 极度颜控。看到长得好看的男子，脚就走不动道，会主动上前搭讪甚至出手“试探”对方的武功。',
      relationship: '穆心兰 (奶奶/前代掌门): 敬畏与叛逆。害怕奶奶的拐杖和唠叨，表面上乖乖听话，背地里却总是盘算着怎么溜下山去看俊俏少侠。；俊俏的少侠: 狩猎目标。遇到长得好看的年轻男子，她总是忍不住凑上前去搭话。；品行不端/花心之人: 垃圾。一旦发现长得好看的男子是个薄情寡义的骗子，她会立刻翻脸，下手比谁都狠。',
