      name: '乌里蒙',
      description:
        '男，42岁。五毒教大祭司，教主蓝彩鸾之父，人称「五毒教大祭司」。身形极其魁梧高大，远超寻常苗人。披散着一头浓密的狂乱长发，发丝间夹杂着几缕灰白。赤裸着上身，胸膛和双臂上布满暗青色的毒纹与交错的刀疤。',
      personality: '带领五毒教打出十万大山，在江湖上杀出赫赫威名，让中原人再也不敢随意残杀苗人。 性情极其狂躁暴烈，说话声音如洪钟，稍有不顺心便会砸碎身边的物件。',
      relationship: '蓝彩鸾 (教主/女儿): 复杂的父女情。妻子死后，女儿随母姓并接任教主。两人在门派发展路线上严重相左。每次长老大会，他都会拍着桌子怒吼着要打出苗疆，女儿则冷脸驳回，最后往往以他摔门而去告终，但私下里绝不允许任何人质疑女儿的教主之位。；阿娜依 (圣女/堂侄女): 疼爱与纵容。视其如己出，知道她偷偷溜出苗疆不仅没有阻拦，反而暗中派人保护，希望她能在外面闯出一片天。；中原武林人士: 刻骨仇恨。见一个杀一个，出手极其残忍，绝不留活口。',
      location: '西南 · 五毒岭',
