      look: {head:'heads_human_male',hair:'hair_buzzcut','hairColor':'dark_gray',skin:'bronze',torso:'torso_clothes_longsleeve2','clothColor':'maroon',legs:'legs_pants',feet:'feet_boots_basic',arms:'arms_bracers',brows:'eyebrows_thin',nose:'head_nose_straight',eye:'brown',beard:'',note:'男，42岁，五毒教大祭司，教主蓝彩鸾之父'},
