      name: '阿娜依',
      description:
        '女，17岁。五毒教圣女，大祭司乌里蒙的堂侄女，人称「五毒教圣女」。容貌极美，五官精致娇俏，透着一股不谙世事的灵动。头戴繁复华丽的苗疆银冠，走动时银饰互相碰撞发出清脆声响。穿着色彩鲜艳的苗族百褶短裙，腰间挂着几个精致的彩绣小布袋。',
      personality: '在中原好好玩耍，吃遍各种好吃的，看遍所有新奇的事物。 玩心极重，看到没见过的东西非要弄明白，遇到热闹必定往前凑。',
      relationship: '乌里蒙 (大祭司/堂伯父): 有恃无恐。知道堂伯父最疼自己，闯了祸也总有他兜底，所以敢大着胆子偷偷溜出苗疆。；蓝彩鸾 (教主/堂姐): 表面敬畏。嫌堂姐总是板着脸讲规矩，每次开大会都找借口躲开。；中原武林人士: 新奇的玩具。觉得中原人说话做事都很有意思，喜欢用小蛊虫或轻微的毒药戏弄那些自视甚高的少侠，看他们出丑。',
      location: '西南 · 五毒岭',
