      name: '蓝彩鸾',
      description:
        '女，24岁。五毒教现任教主，乌里蒙之女，人称「五毒教主」。穿着深蓝色的苗疆劲装，服饰上没有多余的银饰和铃铛，极为干练。面容清冷白皙，眉宇间带着不容置疑的威严与坚毅。长发用一根暗银色的蛇形发簪高高盘起。',
      personality: '在朝廷异动与江湖乱局中，稳住五毒教的基业，寻找最安全的时机再让苗人走出去。 极度冷静沉稳，说话字字千钧，从不废话。',
      relationship: '乌里蒙 (大祭司/父亲): 理念冲突的血亲。理解父亲的仇恨，但认为现在出苗疆只会给五毒教带来灭顶之灾。在大会上任由父亲咆哮，绝不妥协；但私下里会暗中处理掉那些试图利用父亲激进情绪的长老。；阿娜依 (圣女/堂妹): 纵容。知道她溜出去了，不仅没派人抓她回来，反而觉得让她在中原搅局，或许能替自己试探出朝廷的深浅。；皇城司/朝廷暗探: 警惕对象。察觉到近年来朝廷在西南的异常举动，暗中拔除了多个潜入苗疆的皇城司据点。',
