      name: '陆谭生',
      description:
        '男，45岁。白莲教江南总坛主，江南某镇教书先生。白日里穿着洗得发白的青色儒衫，头发用木簪束起。面容清癯，蓄着三绺长须，常拿着一卷书或一把戒尺。夜晚主持集会时，会换上纯白色的宽大罩袍，头戴遮掩面容的白莲面具。',
      personality: '替前代教主守住并壮大白莲教的基业，保护好自己的小家。 极度割裂的双面生活。白天在私塾里教孩童念《论语》，对妻子温声细语；每月十五的夜晚，便孤身进山，站在高台上对着数千名农户进行极具煽动性的演讲。',
      relationship: '前代教主 (旧主): 绝对的忠诚与怀念。自幼作为书童陪其长大，将白莲教的基业视为前代教主留下的最宝贵的东西。；唐婉儿 (现任教主/小魔女): 无奈与纵容。视其为晚辈，任由她当甩手掌柜游山玩水，自己默默扛起江南教务的重担。；家人 (妻子与一双儿女): 最后的温情。对家人极其温和，严密地将他们与白莲教的事务隔离开来。家人只当他是个穷酸但善良的教书先生。',
      location: '无定所',
