      description:
        '男，35岁。白莲教香主，负责乡野农户传教，人称「白莲教香主」。穿着洗得发白、打着补丁的破旧儒衫，头戴方巾。面容消瘦，颧骨突出，眼眶微陷。手指因为常年握笔而带有墨迹，但指节粗大，带有些许干农活留下的茧子。',
      personality: '煽动农户造反，借白莲教的势推翻朝廷，自己好封侯拜相，报复科举不公。 常年在田间地头、村口老树下活动。',
      relationship: '陆谭生 (江南总坛主/顶头上司): 畏惧且嫉妒。害怕陆谭生的雷霆手段，但私下里嫉妒对方能当上总坛主，认为自己才高八斗，早晚能取而代之。；底层农户: 蛊惑对象。视他们为自己往上爬的踏脚石，表面上称兄道弟，实则内心极度鄙夷他们的愚昧。；朝廷官员: 刻骨仇恨。因屡试不中，将所有怨气发泄在朝廷身上，发誓要将那些考官踩在脚下。',
