      personality: '在市井中拉帮结派，大肆敛财，享受被底层穷苦人拥簇和尊重的滋味。 在码头、瓦肆开了一家破旧的茶水铺作为掩护。',
      relationship: '陆谭生 (江南总坛主): 敬畏与巴结。定期上交香火钱，极力讨好总坛主以保住自己的地位。；城镇苦力/流民/娼妓: 拉拢对象。用一碗热粥或一副廉价的膏药收买他们，在他们眼中是活菩萨般的“三娘”。；地痞流氓: 互相利用。借白莲教的势收编地痞，让他们充当打手，帮自己敛财。',
