      name: '颜兴国',
      description:
        '男，52岁。大延王朝左相，百官之首，人称「左相」。常穿绯色一品仙鹤补服，或是极素净的灰色长衫。身材清瘦挺拔，脊背永远笔直。留着修剪整齐的三绺长须，夹杂着些许灰白。行事：极少显露真实情绪，说话总是慢条斯理，滴水不漏。',
      personality: '维持颜家在大延朝堂的绝对权力；以天下为棋盘，制衡各方势力。 极少显露真实情绪，说话总是慢条斯理，滴水不漏。',
      relationship: '赵德昭 (皇帝): 君臣。表面绝对恭顺，实则在皇帝重病之际，已开始为新君登基和家族延续暗中铺路。；右相 (政敌): 势同水火。右相掌管兵部与镇武台，偏向武力镇压；颜兴国掌管吏部与宗教，主张分化瓦解。；颜若华 (长女): 嫡出长女。精通琴棋书画与相府内务，是颜兴国最满意的“完美相府千金”，常替他打理文臣女眷的人脉。',
      location: '大延 · 行走江湖',
