      name: '颜若华',
      description:
        '女，19岁。左相府大小姐，明教光明特使，人称「无」。常穿月白或淡青色的丝绸对襟长裙，裙摆绣着极雅致的兰花，衣料考究但不奢华。与妹妹颜若昭生得一模一样，但气质截然不同。若华眉眼低垂，气质温婉恬静，书卷气极浓。皮肤白皙细腻，十指纤长柔软，指腹仅在拨弄琴弦的位置有极薄的茧。',
      personality: '保护妹妹；维持相府的安宁；在力所能及的范围内庇护苦命的教众。 性格极其纯良温和，连踩死一只蚂蚁都会不忍。遇到纷争总是优先讲道理或用相府千金的身份息事宁人。',
      relationship: '颜兴国 (父亲): 敬畏与孝顺。她是相府的门面，完美地扮演着父亲期望的千金大小姐角色，帮父亲打理内宅与文臣女眷的人脉。；颜若昭 (双胞胎妹妹): 极度疼爱。知道妹妹从小习武打熬筋骨的辛苦，总是把最好的伤药和点心留给妹妹。姐妹俩是彼此唯一的知己。；明教潜伏教众: 悲悯的庇护者。通过相府的账目和人脉，暗中将部分教众安插在相府的庄园或商铺中，从不让他们参与任何危险任务。',
