      name: '温宁',
      description:
        '女，16岁。不欠客栈老板娘，杀手温渡之女，人称「无」。身形娇小，比同龄女子略矮半头，穿着素净的粗布衣裳，袖口常挽起一截。头发梳成简单的双丫髻，用两根普通的木簪固定，不施粉黛。面容清秀，眉眼弯弯，笑起来嘴角有两个浅浅的梨涡。',
      personality: '把客栈开下去，让三位长辈安稳过日子。 待人接物极有礼貌，说话轻声细语，但话里带着几分机灵，从不吃亏。',
      relationship: '温渡 (父亲/已故): 敬爱与思念。父亲是杀手，但对她极好，从小教她暗器机关，教她识字算账，教她“做人要干净”。父亲旧伤发作过世后，她接了客栈。；沈昭 (会计): 依赖与亲近。叫她“昭姐”。知道昭姐心里有事，但从不追问。昭姐教她算账，她教昭姐认野菜。；田世平 (厨子): 亲近与敬重。叫他“厉叔”。觉得厉叔切菜的样子很好看，但从不提他脸上的疤。',
      location: '雁门关外 · 不欠客栈',
