      name: '沈昭',
      description:
        '女，28岁。不欠客栈账房，原龙泉沈家试剑人，人称「无」。身形高挑瘦削，站姿笔直，如一把立着的剑。常年穿着一身洗得发旧的月白色长衫，袖口收得极紧，衣摆裁短便于行走。面容清冷，五官端正，眉宇间带着一股化不开的倦意与傲气。',
      personality: '守住客栈的账，守住自己最后一点体面。 对生人极冷，说话简短，眼神锐利，看人先看对方的手和兵器。',
      relationship: '沈家 (家族): 愧疚与逃避。十二年前剑断之后，她没脸回龙泉。她怕的不是被责怪，是怕看到家族失望的眼神。；温宁 (老板娘): 依赖与亲近。叫她“阿念”。教阿念算账，阿念教她认野菜。阿念是她在这世上唯一能放松下来的人。；田世平 (厨子): 沉默的默契。两人都经历过十二年前那场混战，却从不说破。偶尔会在后院对坐，一言不发，各喝各的酒。',
