      description:
        '男，58岁。不欠客栈小二，原嵩山派高功，人称「无」。身形瘦高，但常年佝偻着背，显得比实际身高矮了一截。穿着一身洗得发白的灰布短打，外面罩着一件旧棉褂，袖口和下摆都打着补丁。面容清癯，皱纹深重，颧骨高耸，下颌留着稀疏的花白胡须。',
      personality: '把剩下的日子过好，把肚子里那些江湖旧事讲给愿意听的人。 每天坐在客栈门口，一边晒太阳一边拿蒲扇扇风，见到路过的客人就吆喝一嗓子“客官住店还是打尖”。',
      relationship: '嵩山派 (旧师门): 早已散了的门派。他离开时，嵩山已是一片废墟，无人可守，无门可归。；温宁 (老板娘): 视如孙女。叫她“阿念”。最喜欢逗她，但从不真惹她生气。；沈昭 (账房): 敬重。知道沈昭是龙泉沈家的试剑人，偶尔会向她请教兵刃与门派的来历。沈昭冷，他也不热，两人相处倒自在。',
