      description:
        '男，26岁。六扇门首席智囊，总捕头之下第一人，人称「无情」。身形清瘦，常穿着一件洗得发白的青布长衫，衣摆裁短，便于轮椅活动。面容清俊，眉眼细长，眼神平静，极少有情绪波动。双腿自膝下废去，常年坐在一张特制的木轮椅上，轮椅扶手内藏机括，椅背可拆可合。',
      personality: '把每一个案子办成铁案，让朝廷的规矩立得住。 说话极少，语速偏慢，用词精准，从不废话。',
