      name: '铁少游',
      description:
        '男，46岁。六扇门总捕头，四捕之首，人称「铁面总捕」。身形中等偏壮，肩膀宽厚，站着时如一堵墙。常年穿着一身玄色公服，衣料厚实，袖口扎紧，腰间系着一根旧皮带。面容方正，颧骨高耸，眉心有一道常年皱眉留下的竖纹，常年不苟言笑。',
      personality: '把每一个案子办成铁案，让朝廷的规矩立得住，让江湖知道“王法还在”。 话不多，但每句话都掷地有声。下达命令时字字千钧，从不解释。',
      relationship: '温无算 (无情): 敬重与默契。温无算负责“智”，他负责“稳”。两人配合多年，六扇门大案多由温无算布局，他执行。；陆寻风 (追命): 信任。陆寻风追人从不失手，他放心把“追”这一环交给陆寻风。；寒不语 (冷血): 放心。寒不语出手狠辣，专办最危险的案子，他放心把“杀”这一环交给寒不语。',
